import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1

    if opp_c == n:
        if n >= 88:
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    coop = opp_c / float(n)

    # Count opponent's trailing streak
    same = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same += 1
        else:
            break

    # Endgame exploitation of a sufficiently cooperative opponent
    if n >= 92:
        if coop >= 0.6 and opp_last == 'C':
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    if n >= 85:
        if coop >= 0.55 and opp_last == 'C':
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Very exploitative opponent: punish hard
    if coop <= 0.15 and n >= 6:
        return 'D'

    # Long defection streak: mostly resist, occasional olive branch
    if opp_last == 'D' and same >= 4:
        if n < 85 and rng.randint(0, 5) == 0:
            return 'C'
        return 'D'

    # Long cooperation streak: quiet cooperation, rare probe
    if opp_last == 'C' and same >= 5:
        if n < 80 and rng.randint(0, 24) == 0:
            return 'D'
        return 'C'

    # Tit-for-tat core with mild forgiveness
    if opp_last == 'C':
        if my_last == 'D' and n < 90 and rng.randint(0, 6) == 0:
            return 'D'
        return 'C'

    # Opponent defected: retaliate, but with a small cooperative chance
    def_ratio = (cd + dd) / float(n)
    if def_ratio < 0.25 and n >= 10:
        if rng.randint(0, 3) == 0:
            return 'C'
        return 'D'
    if rng.randint(0, 9) == 0:
        return 'C'
    return 'D'
